
(function(){
  const CT_INCOME_WORKSHEET_B64 = "";
  window.ctDownloadIncomeWorksheet = function(){
    try{
      const raw=atob(CT_INCOME_WORKSHEET_B64);
      const bytes=new Uint8Array(raw.length);
      for(let i=0;i<raw.length;i++) bytes[i]=raw.charCodeAt(i);
      const file=new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
      const url=URL.createObjectURL(file);
      const a=document.createElement('a');
      a.href=url;
      a.download='Income-Worksheet-Macro-Free.xlsx';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(()=>URL.revokeObjectURL(url),1500);
      if(typeof ctShowToast==='function') ctShowToast('Income worksheet ready.');
    }catch(err){
      console.error('Income worksheet download failed',err);
      if(typeof ctShowToast==='function') ctShowToast('Could not open the income worksheet. Please refresh and try again.');
      else alert('Could not open the income worksheet. Please refresh and try again.');
    }
  };
})();
